    int m = (1 << (bits - 1));
    uint32_t mask = 1 << t;
    int q = 0;
    for (int i = 0; i < bits; ++i)
        q |= ((bitplanes[warp_id][i] & mask) >> t) << i;

    // Dequantize
    float v = __int2float_rn(q - m);
    v /= __int2float_rn(m);

    // Scale and rotate
    v *= s;
    v = shuffle_had_fx32(v, t);
    v *= 0.17678f;  // 0.17678 = 1 / sqrt(32)

